  1	-- migrate:up
  2	
  3	-- Store an owned web conversation's route segment instead of reconstructing it
  4	-- from conversation_id on every list read. Platform conversations continue to
  5	-- route by their complete conversation_id.
  6	ALTER TABLE public.conversations
  7	  ADD COLUMN IF NOT EXISTS thread_id text;
  8	
  9	-- Migrations run before the app deployment changes, so an old server can still
 10	-- insert rows after the backfill. Fill packed web ids at the database boundary
 11	-- during that compatibility window; opaque owned ids remain unlisted, matching
 12	-- the old reader.
 13	CREATE OR REPLACE FUNCTION public.conversations_fill_thread_id()
 14	RETURNS trigger
 15	LANGUAGE plpgsql
 16	AS $$
 17	DECLARE
 18	  prefix text;
 19	BEGIN
 20	  IF NEW.thread_id IS NOT NULL
 21	     OR NEW.kind <> 'owned'
 22	     OR NEW.user_id IS NULL THEN
 23	    RETURN NEW;
 24	  END IF;
 25	
 26	  prefix := NEW.agent_id || '_' || NEW.user_id || '_' || NEW.organization_id || '_';
 27	
 28	  IF left(NEW.conversation_id, length(prefix)) = prefix
 29	     AND length(NEW.conversation_id) > length(prefix) THEN
 30	    -- Packed web id: the routable thread id is the suffix.
 31	    NEW.thread_id := substring(NEW.conversation_id from length(prefix) + 1);
 32	  END IF;
 33	  -- Otherwise leave NULL: either the default id has no thread suffix or the id
 34	  -- has a foreign shape. Both remain unlisted, matching the old reader.
 35	
 36	  RETURN NEW;
 37	END;
 38	$$;
 39	
 40	-- The embedded migrator can replay SQL before recording its ledger row.
 41	DROP TRIGGER IF EXISTS conversations_fill_thread_id ON public.conversations;
 42	CREATE TRIGGER conversations_fill_thread_id
 43	  BEFORE INSERT OR UPDATE OF thread_id ON public.conversations
 44	  FOR EACH ROW
 45	  EXECUTE FUNCTION public.conversations_fill_thread_id();
 46	
 47	-- Backfill only the exact known-column prefix the old reader stripped. LIKE
 48	-- would treat underscores in ids as wildcards and could materialize a false
 49	-- route for a foreign-shaped conversation id.
 50	UPDATE public.conversations
 51	   SET thread_id = substring(
 52	         conversation_id
 53	         from (length(agent_id || '_' || user_id || '_' || organization_id || '_') + 1)
 54	       )
 55	 WHERE kind = 'owned'
 56	   AND user_id IS NOT NULL
 57	   AND thread_id IS NULL
 58	   AND left(
 59	         conversation_id,
 60	         length(agent_id || '_' || user_id || '_' || organization_id || '_')
 61	       ) = agent_id || '_' || user_id || '_' || organization_id || '_'
 62	   AND length(conversation_id)
 63	       > length(agent_id || '_' || user_id || '_' || organization_id || '_');
 64	
 65	-- migrate:down
 66	DROP TRIGGER IF EXISTS conversations_fill_thread_id ON public.conversations;
 67	DROP FUNCTION IF EXISTS public.conversations_fill_thread_id();
 68	-- squawk-ignore ban-drop-column -- rollback path for the column introduced here
 69	ALTER TABLE public.conversations
 70	  DROP COLUMN IF EXISTS thread_id;
  1	/**
  2	 * Composite conversation ids for the web-panel Agent API (`POST /api/v1/agents`).
  3	 * Watcher automation is exempt from org scoping — pass `organizationId: undefined`
  4	 * for that path (see `routes/public/agent.ts`).
  5	 */
  6	
  7	/**
  8	 * Inverse of {@link buildApiConversationId}: recover the `threadId` suffix from a
  9	 * packed web/API conversation id using its known owner columns.
 10	 *
 11	 * This runs at write time so the result can be stored in
 12	 * `conversations.thread_id`; list readers do not parse the id string again.
 13	 * Returns null when the id is not packed for this owner or has no thread suffix.
 14	 *
 15	 * NOTE for a future origin with OPAQUE ids (an MCP session, a behaviour run):
 16	 * storing the id verbatim here is NOT enough to make it work, and is why that
 17	 * case is deliberately still null. The thread read path re-PACKS the id —
 18	 * `readThreadMessages` and the interactions query in `routes/public/agent-history.ts`
 19	 * both call {@link buildApiConversationId} with the thread id — so an opaque
 20	 * value would list in the sidebar and then resolve to a conversation id no row
 21	 * has. Making those origins listable means teaching the read path to address a
 22	 * conversation by its stored id, not just widening what gets stored.
 23	 */
 24	export function threadIdFromApiConversationId(args: {
 25		conversationId: string;
 26		agentId: string;
 27		userId: string;
 28		organizationId?: string;
 29	}): string | null {
 30		const orgScope = args.organizationId ? `_${args.organizationId}` : "";
 31		const prefix = `${args.agentId}_${args.userId}${orgScope}_`;
 32		if (!args.conversationId.startsWith(prefix)) return null;
 33		const suffix = args.conversationId.slice(prefix.length);
 34		return suffix.length > 0 ? suffix : null;
 35	}
 36	
 37	export function buildApiConversationId(args: {
 38		agentId: string;
 39		userId: string;
 40		organizationId?: string;
 41		threadId?: string;
 42	}): string {
 43		const orgScope = args.organizationId ? `_${args.organizationId}` : "";
 44		if (args.threadId) {
 45			return `${args.agentId}_${args.userId}${orgScope}_${args.threadId}`;
 46		}
 47		return `${args.agentId}_${args.userId}${orgScope}`;
 48	}
