108	export interface ConversationListRow {
109		platform: string;
110		conversationId: string;
111		/**
112		 * Web route segment for an owned conversation. Platform rows route by
113		 * `conversationId`; an owned row with null here is not listable.
114		 */
115		threadId: string | null;
116		kind: ConversationKind;
117		userId: string | null;
118		title: string | null;
119		lastActivityAt: Date;
