123	/**
124	 * Read one conversation row by its full PK. Returns null when the row does not
125	 * exist (or is soft-deleted). The single get source, mirroring
126	 * {@link listConversations}'s read of the materialized entity.
127	 */
128	export async function getConversation(args: {
129		organizationId: string;
130		agentId: string;
131		platform: string;
132		conversationId: string;
133	}): Promise<ConversationListRow | null> {
134		const { organizationId, agentId, platform, conversationId } = args;
135		const sql = getDb();
136		const rows = await sql<{
137			platform: string;
138			conversation_id: string;
139			thread_id: string | null;
140			kind: ConversationKind;
141			user_id: string | null;
142			title: string | null;
143			last_activity_at: Date | null;
144			created_at: Date;
145		}>`
146	    SELECT platform, conversation_id, thread_id, kind, user_id, title,
147	           last_activity_at, created_at
148	    FROM public.conversations
149	    WHERE organization_id = ${organizationId}
150	      AND agent_id = ${agentId}
151	      AND platform = ${platform}
152	      AND conversation_id = ${conversationId}
153	      AND archived_at IS NULL
154	    LIMIT 1
155	  `;
156		const r = rows[0];
157		if (!r) return null;
158		return {
159			platform: r.platform,
160			conversationId: r.conversation_id,
161			threadId: r.thread_id,
162			kind: r.kind,
163			userId: r.user_id,
164			title: r.title,
165			lastActivityAt: r.last_activity_at ?? r.created_at,
166			createdAt: r.created_at,
167		};
168	}
