170	/**
171	 * A turn's terminal outcome, read from the durable `runs` thread-response rows
172	 * the worker writes on completion. Cross-replica-safe (Postgres, not the
173	 * pod-local SSE buffer) — so `conversations.send({ wait: true })` can await a
174	 * reply without holding an SSE socket.
175	 */
176	export type ConversationReply =
177		| { status: "complete"; text: string }
178		| { status: "error"; error: string };
179	
180	/**
181	 * Poll for the terminal outcome of a dispatched message. Matches the completion
182	 * row the worker writes to `public.runs` (queue_name='thread_response') whose
183	 * payload lists `messageId` in `processedMessageIds` (a turn can batch several).
184	 * Returns null while the turn is still in flight. `finalText` carries the full
185	 * assistant reply on the terminal row (see ThreadResponsePayload.finalText).
186	 */
187	export async function readConversationReply(args: {
188		organizationId: string;
189		conversationId: string;
190		messageId: string;
191	}): Promise<ConversationReply | null> {
192		const { organizationId, conversationId, messageId } = args;
193		const sql = getDb();
194		const rows = await sql<{ payload: Record<string, unknown> | null }>`
195	    WITH response_rows AS (
196	      SELECT id,
197	             CASE
198	               WHEN jsonb_typeof(action_input) = 'string'
199	                 THEN (action_input #>> '{}')::jsonb
200	               ELSE action_input
201	             END AS payload
202	      FROM public.runs
203	      WHERE organization_id = ${organizationId}
204	        AND run_type = 'chat_message'
205	        AND queue_name = 'thread_response'
206	        AND status IN ('completed', 'failed')
207	        AND action_input IS NOT NULL
208	    )
209	    SELECT payload
210	    FROM response_rows
211	    WHERE payload->>'conversationId' = ${conversationId}
212	      AND (
213	        payload->>'messageId' = ${messageId}
214	        OR payload->'processedMessageIds' ? ${messageId}
215	      )
216	      AND (payload ? 'error' OR payload ? 'processedMessageIds')
217	    ORDER BY id DESC
218	    LIMIT 1
219	  `;
220		const payload = rows[0]?.payload;
221		if (!payload || typeof payload !== "object") return null;
222		if (typeof payload.error === "string" && payload.error.length > 0) {
223			return { status: "error", error: payload.error };
224		}
225		const finalText =
226			typeof payload.finalText === "string" ? payload.finalText : "";
227		return { status: "complete", text: finalText };
228	}
