230	/**
231	 * List an agent's conversations for the sidebar, newest-first. The single
232	 * listing source: reads the materialized entity instead of deriving from
233	 * `DISTINCT ON (conversation_id) FROM agent_transcript_snapshot`.
234	 *
235	 * Returns owned + platform rows; the caller layers on per-conversation
236	 * visibility (platform ACL) and stitches in the derived watcher entries.
237	 */
238	export async function listConversations(args: {
239		organizationId: string;
240		agentId: string;
241		/** "user": only this user's owned conversations. "all": every conversation. */
242		scope: "user" | "all";
243		userId: string;
244	}): Promise<ConversationListRow[]> {
245		const { organizationId, agentId, scope, userId } = args;
246		const sql = getDb();
247		const rows = await sql<{
248			platform: string;
249			conversation_id: string;
250			thread_id: string | null;
251			kind: ConversationKind;
252			user_id: string | null;
253			title: string | null;
254			last_activity_at: Date | null;
255			created_at: Date;
256		}>`
257	    SELECT platform, conversation_id, thread_id, kind, user_id, title,
258	           last_activity_at, created_at
259	    FROM public.conversations
260	    WHERE organization_id = ${organizationId}
261	      AND agent_id = ${agentId}
262	      AND archived_at IS NULL
263	      ${
264					scope === "user"
265						? sql`AND kind = 'owned' AND user_id = ${userId}`
266						: sql``
267				}
268	    ORDER BY last_activity_at DESC NULLS LAST, created_at DESC
269	  `;
270		return rows.map((r) => ({
271			platform: r.platform,
272			conversationId: r.conversation_id,
273			threadId: r.thread_id,
274			kind: r.kind,
275			userId: r.user_id,
276			title: r.title,
277			lastActivityAt: r.last_activity_at ?? r.created_at,
278			createdAt: r.created_at,
279		}));
280	}
