 12	import { paginateSessionMessages } from "./session-message-page.js";
 13	import { readSnapshotJsonl } from "./transcript-snapshot.js";
 14	
 15	const SAFE_AGENT_ID = /^[a-zA-Z0-9_-]+$/;
 16	const SAFE_THREAD_ID = /^[a-zA-Z0-9_-]+$/;
 17	
 18	function isSafeAgentId(id: string): boolean {
 19		return SAFE_AGENT_ID.test(id);
 20	}
 21	
 22	function isSafeThreadId(id: string): boolean {
 23		return SAFE_THREAD_ID.test(id);
 24	}
 25	
 26	export interface AgentThreadSummary {
 27		/** Routing key: a thread id for web conversations (chattable), or the raw
 28		 *  conversation id for platform conversations (read-only). */
 29		id: string;
 30		title: string;
 31		createdAt: number;
 32		updatedAt: number;
 33		/** "web" for the app's own threads; "behavior" for behavior activity; otherwise
 34		 *  the source platform derived from the conversation id prefix (slack, …). */
 35		platform: string;
 36		/** Raw conversation id — used to read a platform conversation read-only. */
 37		conversationId: string;
 38		/** Set on `platform: "behavior"` entries — routes to the behavior's page. */
 39		behaviorId?: number;
 40	}
 41	
 42	/** `{platform}:{team}:{channel}` — team-scoped so the same channel id in two
 43	 *  Slack workspaces never collides. `team` is "" for platforms without one. */
 44	function channelVisibilityKey(
 45		platform: string,
 46		teamId: string | null,
 47		bareChannelId: string,
 48	): string {
 49		return `${platform.toLowerCase()}:${teamId ?? ""}:${bareChannelId}`;
 50	}
 51	
 52	export interface ChannelVisibility {
 53		/** Team-scoped keys the requester may read (per-agent fence ∩ per-user ACL). */
 54		visibleKeys: Set<string>;
 55		/** `{platform}:{channel}` → the team ids the AGENT is bound to it in. A
 56		 *  channel bound in >1 team can't be disambiguated from a conversation id
 57		 *  alone, so it fails closed. */
 58		channelTeams: Map<string, Set<string>>;
 59	}
 60	
 61	/**
 62	 * Which channels may THIS requester read for THIS agent — the per-agent channel
 63	 * fence (the agent's bound channels) INTERSECTED with the per-user channel ACL
 64	 * gate ({@link filterChannelsForRequester}), team-scoped. A platform conversation
 65	 * is visible iff {@link isConversationVisible}. Mirrors recall's gate so a user
 66	 * never sees a channel transcript they're not a member of.
 67	 */
 68	export async function resolveChannelVisibility(
 69		sql: DbClient,
 70		args: {
 71			organizationId: string;
 72			agentId: string;
 73			userId: string | null;
 74			allowNotGraphed?: boolean;
 75		},
 76	): Promise<ChannelVisibility> {
 77		const bound = await resolveBoundChannelRows(sql, {
 78			organizationId: args.organizationId,
 79			agentId: args.agentId,
 80		});
 81		const channelTeams = new Map<string, Set<string>>();
 82		for (const c of bound) {
 83			const bare = stripPlatformPrefix(c.platform, c.channel_id);
 84			const pc = `${c.platform.toLowerCase()}:${bare}`;
 85			const set = channelTeams.get(pc) ?? new Set<string>();
 86			set.add(c.team_id ?? "");
 87			channelTeams.set(pc, set);
 88		}
 89		const visible = await filterChannelsForRequester(sql, {
 90			organizationId: args.organizationId,
 91			userId: args.userId,
 92			rows: bound,
 93			allowNotGraphed: args.allowNotGraphed,
 94		});
 95		const visibleKeys = new Set(
 96			visible.map((c) =>
 97				channelVisibilityKey(
 98					c.platform,
 99					c.team_id,
100					stripPlatformPrefix(c.platform, c.channel_id),
101				),
102			),
103		);
104		return { visibleKeys, channelTeams };
105	}
106	
107	/** Can the requester read this platform conversation (`{platform}:{channel}:{thread}`)?
108	 *  Fail-closed: unbound, or a channel bound in ≥2 DISTINCT REAL workspaces (can't
109	 *  tie the conversation to a single team), is not visible.
110	 *
111	 *  A NULL/"" team is a WILDCARD ("workspace unknown yet" — a binding written
112	 *  before its workspace healed from the first inbound event), NOT a distinct
113	 *  workspace. `team_id` is now guaranteed to be a real workspace or NULL (never a
114	 *  Grid enterprise id), so the gate needs zero connector knowledge: it counts
115	 *  distinct non-null teams and only fails closed on genuine cross-workspace
116	 *  ambiguity (2+ real teams). One real team + any number of NULLs resolves to
117	 *  that team; all-NULL resolves via the wildcard visible key. */
118	export function isConversationVisible(
119		conversationId: string,
120		vis: ChannelVisibility,
121	): boolean {
122		const parts = conversationId.split(":");
123		const platform = (parts[0] ?? "").toLowerCase();
124		const channel = parts[1] ?? "";
125		const teams = vis.channelTeams.get(`${platform}:${channel}`);
126		if (!teams || teams.size === 0) return false; // unbound
127		const realTeams = [...teams].filter((t) => t !== "");
128		if (realTeams.length > 1) return false; // genuine cross-workspace ambiguity
129		// One real team (NULLs are wildcards that resolve to it), or all-NULL (a
130		// teamless/unknown-yet binding — resolves via the "" wildcard visible key).
131		const team = realTeams[0] ?? null;
132		return vis.visibleKeys.has(channelVisibilityKey(platform, team, channel));
133	}
