135	async function findConversationSessionFile(
136		agentId: string,
137		conversationId: string,
138	): Promise<string | null> {
139		if (!isSafeAgentId(agentId)) return null;
140		const workspacesRoot = resolve("workspaces");
141		const workspaceDir = resolve(workspacesRoot, agentId);
142		if (!workspaceDir.startsWith(`${workspacesRoot}/`)) return null;
143	
144		const sanitized = sanitizeConversationId(conversationId);
145		const sessionPath = join(
146			workspaceDir,
147			sanitized,
148			".lobu",
149			"session.jsonl",
150		);
151		try {
152			await stat(sessionPath);
153			return sessionPath;
154		} catch {
155			return null;
156		}
157	}
