159	export async function listAgentThreads(args: {
160		agentId: string;
161		organizationId?: string;
162		userId: string;
163		/** "user" (default): only the requesting user's app threads. "all": every
164		 *  conversation for the agent across platforms (Slack, Telegram, …). */
165		scope?: "user" | "all";
166	}): Promise<AgentThreadSummary[]> {
167		const { agentId, organizationId, userId, scope = "user" } = args;
168		// No org → no tenant scope → nothing to list from the (org-keyed) entity.
