   394		async function canUseSystemAgent(
   395			agentId: string,
   396			organizationId: string,
   397			userId: string,
   398		): Promise<boolean> {
   399			const rows = await getDb()`
   400				SELECT 1
   401				FROM "organization" o
   402				JOIN "member" m ON m."organizationId" = o.id
   403				WHERE o.id = ${organizationId}
   404					AND o.system_agent_id = ${agentId}
   405					AND m."userId" = ${userId}
   406					AND m.role IN ('owner', 'admin')
   407				LIMIT 1
   408			`;
   409			return rows.length > 0;
   410		}
