   412		async function getAuthorizedAgentScope(c: Context): Promise<{
   413			agentId: string;
   414			organizationId: string | undefined;
   415			userId: string;
   416		} | null> {
   417			const session = await verifySettingsSession(c);
   418			if (!session) return null;
   419			const agentId = c.req.param("agentId") || session.agentId || null;
   420			if (!agentId || !isSafeAgentId(agentId)) return null;
   421			const userId = resolveSettingsLookupUserId(session);
   422			const ambientOrgId = resolveOrgId();
   423	
   424			// Apply the resolver's admin bypass and agent-binding restriction before
   425			// selecting a tenant from the ambient request.
   426			if (session.isAdmin) {
   427				return {
   428					agentId,
   429					organizationId: ambientOrgId ?? undefined,
   430					userId,
   431				};
   432			}
   433			if (session.agentId && session.agentId !== agentId) return null;
   434	
   435			// The SPA sends x-lobu-org for the workspace being viewed. Its
   436			// membership-verified ambient org must win over ownership-first resolution
   437			// because the same system-agent id exists in every organization.
   438			if (ambientOrgId) {
   439				const ownsHere =
   440					(await deps.userAgentsStore?.ownsAgent(
   441						session.platform,
   442						userId,
   443						agentId,
   444						ambientOrgId,
   445					)) ?? false;
