   482			const agentId = c.req.param("agentId") || session.agentId || null;
   483			if (!agentId || !isSafeAgentId(agentId)) return null;
   484			const userId = resolveSettingsLookupUserId(session);
   485	
   486			// A shared system-agent id can resolve to an ownership row in another org.
   487			// Keep both the transcript lookup and owner check in the ambient org.
   488			const ambientOrgId = resolveOrgId();
   489			if (!ambientOrgId) return null;
   490	
   491			// Preserve the ownership resolver's platform-admin bypass, scoped to the
   492			// ambient org. Runs before the agent-binding check so an admin's request
   493			// isn't rejected by a session bound to another agent.
   494			if (session.isAdmin) {
   495				return {
   496					agentId,
   497					organizationId: ambientOrgId,
   498					userId,
   499					allowNotGraphed: true,
   500				};
   501			}
   502			if (session.agentId && session.agentId !== agentId) return null;
   503	
   504			const ownsHere =
   505				(await deps.userAgentsStore?.ownsAgent(
   506					session.platform,
   507					userId,
   508					agentId,
   509					ambientOrgId,
   510				)) ?? false;
   511			if (ownsHere) {
   512				return {
   513					agentId,
   514					organizationId: ambientOrgId,
   515					userId,
   516					allowNotGraphed: true,
   517				};
   518			}
