   531				metadata?.owner &&
   532				metadata.organizationId === ambientOrgId &&
   533				sessionMatchesMetadataOwner(
   534					session,
   535					metadata.owner.platform,
   536					metadata.owner.userId,
   537				)
   538			) {
   539				deps.userAgentsStore
   540					?.addAgent(session.platform, userId, agentId, ambientOrgId)
   541					.catch(() => {
   542						/* best-effort reconciliation */
   543					});
   544				return {
   545					agentId,
   546					organizationId: ambientOrgId,
   547					userId,
   548					allowNotGraphed: true,
   549				};
   550			}
   551	
   552			return {
   553				agentId,
   554				organizationId: ambientOrgId,
   555				userId,
   556				allowNotGraphed: false,
   557			};
   558		}
