  77	// Periodic cleanup of stale IN-MEMORY sessions. This must stay as a per-pod
  78	// setInterval — each pod owns its own `sessions` Map of live MCP transports
  79	// and only it can call `entry.transport.close?.()`. The DB-side cleanup
  80	// (mcpSessionStore.deleteExpiredSessions) is registered as a cross-pod
  81	// scheduler task in scheduled/jobs.ts so it runs once per cluster per tick.
  82	setInterval(() => {
  83	  const now = Date.now();
  84	  for (const [id, entry] of sessions) {
  85	    if (now - entry.lastAccessedAt > SESSION_MAX_AGE_MS) {
  86	      sessions.delete(id);
  87	      entry.transport.close?.();
  88	    }
  89	  }
  90	}, SESSION_CLEANUP_INTERVAL_MS).unref();
