 102	export async function revokeInMemoryMcpSessionsForClient(
 103	  clientId: string,
 104	  organizationId: string
 105	): Promise<string[]> {
 106	  const revokedSessionIds: string[] = [];
 107	
 108	  for (const [sessionId, entry] of sessions.entries()) {
 109	    if (entry.authCtx.clientId !== clientId || entry.authCtx.organizationId !== organizationId) {
 110	      continue;
 111	    }
 112	
 113	    revokedSessionIds.push(sessionId);
 114	    sessions.delete(sessionId);
 115	    await deletePersistedSession(sessionId);
 116	    entry.transport.close?.();
 117	  }
 118	
 119	  return revokedSessionIds;
 120	}
