 405	async function readInitializeRequest(req: Request): Promise<{
 406	  id: string | number | null;
 407	  requestedAgentId: string | null;
 408	  clientInfo: Record<string, unknown> | null;
 409	  capabilities: Record<string, unknown> | null;
 410	} | null> {
 411	  const headerAgentId = req.headers.get('x-lobu-agent-id')?.trim() || null;
 412	  try {
 413	    const body = await req.clone().json();
 414	    const messages = Array.isArray(body) ? body : [body];
 415	    const initialize = messages.find((m: any) => m?.method === 'initialize');
 416	    if (!initialize) {
 417	      return headerAgentId
 418	        ? {
 419	            id: null,
 420	            requestedAgentId: headerAgentId,
 421	            clientInfo: null,
 422	            capabilities: null,
 423	          }
 424	        : null;
 425	    }
 426	
 427	    const clientInfo =
 428	      initialize?.params?.clientInfo && typeof initialize.params.clientInfo === 'object'
 429	        ? initialize.params.clientInfo
 430	        : null;
 431	    const capabilities =
 432	      initialize?.params?.capabilities && typeof initialize.params.capabilities === 'object'
 433	        ? initialize.params.capabilities
 434	        : null;
 435	    const bodyAgentId =
 436	      (typeof clientInfo?.agentId === 'string' && clientInfo.agentId.trim()) ||
 437	      (typeof clientInfo?.metadata?.agentId === 'string' && clientInfo.metadata.agentId.trim()) ||
 438	      null;
 439	
 440	    return {
 441	      id: initialize.id ?? null,
 442	      requestedAgentId: headerAgentId ?? bodyAgentId,
 443	      clientInfo,
 444	      capabilities,
 445	    };
 446	  } catch {
 447	    return headerAgentId
 448	      ? {
 449	          id: null,
 450	          requestedAgentId: headerAgentId,
 451	          clientInfo: null,
 452	          capabilities: null,
 453	        }
 454	      : null;
 455	  }
 456	}
