 493	async function resolveMembershipRole(
 494	  env: Env,
 495	  organizationId: string | null,
 496	  userId: string | null
 497	): Promise<string | null> {
 498	  if (!organizationId || !userId) return null;
 499	  const sql = createDbClientFromEnv(env);
 500	  const rows = await sql`
 501	    SELECT role
 502	    FROM "member"
 503	    WHERE "organizationId" = ${organizationId}
 504	      AND "userId" = ${userId}
 505	    LIMIT 1
 506	  `;
 507	  return rows.length > 0 ? ((rows[0].role as string) ?? null) : null;
 508	}
