 510	/**
 511	 * Populate `memberRole` for an authenticated SCOPED (`/mcp/{slug}`) session.
 512	 *
 513	 * `extractAuthContext` derives the org from the URL slug and the user from the
 514	 * token, but never looks up the caller's membership row — so a scoped session's
 515	 * `memberRole` is null even for a real owner/admin. The UNSCOPED path already
 516	 * resolves it via `resolveMembershipRole`; the scoped path historically skipped
 517	 * that, which made every role-gated action (e.g. `manage_catalog.list_installed`,
 518	 * which requires admin) wrongly deny legitimate members over `/mcp/{slug}`.
 519	 *
 520	 * Anonymous public-workspace browse (no userId) keeps a null role by design —
 521	 * `resolveMembershipRole` returns null for a null user, so this is a no-op there.
 522	 */
 523	async function hydrateScopedMemberRole(env: Env, authCtx: AuthContext): Promise<void> {
 524	  if (!authCtx.scopedToOrg || !authCtx.isAuthenticated) return;
 525	  if (!authCtx.organizationId || !authCtx.userId) return;
 526	  authCtx.memberRole = await resolveMembershipRole(env, authCtx.organizationId, authCtx.userId);
 527	}
