 529	async function recoverSessionAuthContext(
 530	  c: Context<{ Bindings: Env }>,
 531	  sessionId: string
 532	): Promise<SessionAuthContext | null> {
 533	  const persisted = await mcpSessionStore.getSession(sessionId);
 534	  if (!persisted) return null;
 535	
 536	  const authCtx = await resolveAuthWithInstructions(c);
 537	
 538	  if (persisted.isAuthenticated) {
 539	    if (!authCtx.isAuthenticated) return null;
 540	    if (persisted.userId && persisted.userId !== authCtx.userId) return null;
 541	    if (persisted.clientId && persisted.clientId !== authCtx.clientId) return null;
 542	  }
 543	
 544	  if (persisted.scopedToOrg !== authCtx.scopedToOrg) {
 545	    return null;
 546	  }
 547	
 548	  if (persisted.scopedToOrg) {
 549	    if (authCtx.organizationId !== persisted.organizationId) {
 550	      return null;
 551	    }
 552	    // Scoped sessions must resolve the caller's membership role too — otherwise
 553	    // role-gated actions deny a legitimate owner/admin over `/mcp/{slug}`.
 554	    await hydrateScopedMemberRole(c.env, authCtx);
 555	  } else {
 556	    authCtx.organizationId = persisted.organizationId;
 557	    authCtx.memberRole = await resolveMembershipRole(
 558	      c.env,
 559	      persisted.organizationId,
 560	      authCtx.userId
 561	    );
 562	
 563	    if (persisted.isAuthenticated && persisted.organizationId && !authCtx.memberRole) {
 564	      return null;
 565	    }
 566	  }
 567	
 568	  // A recovered session cannot move between agents. When the persisted row is
 569	  // unbound, verified request auth may supply one; conflicting bindings fail.
 570	  if (
 571	    authCtx.requestedAgentId &&
 572	    persisted.requestedAgentId &&
 573	    authCtx.requestedAgentId !== persisted.requestedAgentId
 574	  ) {
 575	    return null;
 576	  }
 577	  authCtx.requestedAgentId = persisted.requestedAgentId ?? authCtx.requestedAgentId;
 578	  authCtx.instructions = authCtx.organizationId
 579	    ? ((await buildWorkspaceInstructions(authCtx.organizationId)) ?? undefined)
 580	    : undefined;
 581	
 582	  const bindingError = await syncAgentBinding(authCtx);
 583	  if (bindingError) {
 584	    return null;
 585	  }
 586	
 587	  return authCtx;
 588	}
