 775	// Wrap transport.handleRequest: if the client didn't ask for SSE, convert the
 776	// SSE response back to plain JSON so simple clients get what they expect.
 777	async function handleAndMaybeConvert(
 778	  transport: WebStandardStreamableHTTPServerTransport,
 779	  req: Request,
 780	  wantsSSE: boolean
 781	): Promise<Response> {
 782	  const response = await transport.handleRequest(req);
 783	  if (!wantsSSE && response.headers.get('content-type')?.includes('text/event-stream')) {
 784	    return sseToJson(response);
 785	  }
 786	  // Inject SSE heartbeat pings to keep the stream alive through proxies.
 787	  // Thread the inbound request's AbortSignal so abnormal disconnects clear
 788	  // the interval (same root cause as PR #833/#845).
 789	  return withSSEHeartbeat(response, req.signal);
 790	}
