 796	async function resolveAuthWithInstructions(
 797	  c: Context<{ Bindings: Env }>,
 798	  req?: Request
 799	): Promise<AuthContext & { instructions?: string }> {
 800	  const authCtx: AuthContext & { instructions?: string } = extractAuthContext(c);
 801	  if (req) {
 802	    const initialize = await readInitializeRequest(req);
 803	    // Verified worker auth already supplies an agent. Only fall back to the
 804	    // initialize metadata used by ordinary MCP clients when auth has none.
 805	    authCtx.requestedAgentId = authCtx.requestedAgentId ?? initialize?.requestedAgentId ?? null;
 806	  }
 807	  if (authCtx.organizationId) {
 808	    authCtx.instructions = (await buildWorkspaceInstructions(authCtx.organizationId)) ?? undefined;
 809	  }
 810	  return authCtx;
 811	}
