 813	async function syncAgentBinding(
 814	  authCtx: AuthContext & { instructions?: string }
 815	): Promise<string | null> {
 816	  const requestedAgentId = authCtx.requestedAgentId?.trim() || null;
 817	  authCtx.agentId = null;
 818	
 819	  if (!requestedAgentId) return null;
 820	  if (!isValidAgentId(requestedAgentId)) {
 821	    return 'agentId must be 3-60 lowercase alphanumeric chars with hyphens, starting with a letter';
 822	  }
 823	  if (!authCtx.isAuthenticated) {
 824	    return 'Authentication required to bind MCP sessions to an agent.';
 825	  }
 826	  if (!authCtx.organizationId) {
 827	    return null;
 828	  }
 829	
 830	  const exists = await agentExistsInOrganization(authCtx.organizationId, requestedAgentId);
 831	  if (!exists) {
 832	    return `Agent '${requestedAgentId}' was not found in the current organization.`;
 833	  }
 834	
 835	  authCtx.agentId = requestedAgentId;
 836	  await touchAgentLastUsed(authCtx.organizationId, requestedAgentId);
 837	  return null;
 838	}
