 840	function createSessionTransport(
 841	  env: Env,
 842	  authCtx: SessionAuthContext,
 843	  sessionIdGenerator: () => string,
 844	  resolvedOrigin: string
 845	): { transport: WebStandardStreamableHTTPServerTransport; server: Server } {
 846	  const transport = new WebStandardStreamableHTTPServerTransport({
 847	    sessionIdGenerator,
 848	    onsessioninitialized: (id) => {
 849	      sessions.set(id, {
 850	        transport,
 851	        server,
 852	        authCtx,
 853	        lastAccessedAt: Date.now(),
 854	      });
 855	    },
 856	  });
 857	  transport.onclose = () => {
 858	    if (transport.sessionId) {
 859	      sessions.delete(transport.sessionId);
 860	      void deletePersistedSession(transport.sessionId);
 861	    }
 862	  };
 863	  const server = createServerForContext(env, authCtx, resolvedOrigin);
 864	  return { transport, server };
 865	}
