 910	export async function handleMcp(c: Context<{ Bindings: Env }>): Promise<Response> {
 911	  const wantsSSE = clientAcceptsSSE(c.req.raw);
 912	  const req = normalizeAcceptHeader(c.req.raw);
 913	  const sessionId = req.headers.get('mcp-session-id') ?? undefined;
 914	  formatRef.rawJson = req.headers.get('x-mcp-format')?.toLowerCase() === 'json';
 915	
 916	  // Existing session → reuse
 917	  if (sessionId && sessions.has(sessionId)) {
 918	    const session = sessions.get(sessionId)!;
 919	    session.lastAccessedAt = Date.now();
 920	
 921	    const clearSession = () => {
 922	      sessions.delete(sessionId);
 923	      void deletePersistedSession(sessionId);
 924	    };
 925	
 926	    // Refresh authenticated session context on every request so role changes,
 927	    // scope changes, and auth upgrades are reflected immediately.
 928	    if (c.var.mcpIsAuthenticated) {
 929	      const freshCtx = extractAuthContext(c);
 930	
 931	      if (session.authCtx.isAuthenticated) {
 932	        if (session.authCtx.userId && freshCtx.userId !== session.authCtx.userId) {
 933	          clearSession();
 934	          return buildJsonRpcErrorResponse(
 935	            'Session authentication changed. Re-initialize.',
 936	            null,
 937	            400
 938	          );
 939	        }
 940	        if (session.authCtx.clientId && freshCtx.clientId !== session.authCtx.clientId) {
 941	          clearSession();
 942	          return buildJsonRpcErrorResponse('Session client changed. Re-initialize.', null, 400);
 943	        }
 944	      }
 945	
 946	      session.authCtx.isAuthenticated = true;
 947	      session.authCtx.userId = freshCtx.userId;
 948	      session.authCtx.clientId = freshCtx.clientId;
 949	      // `extractAuthContext` always yields a concrete scope array (real scopes
 950	      // for token callers, the not-applicable sentinel for session/anonymous).
 951	      // Assign it straight through — `hasRequiredMcpScope` fails closed on
 952	      // null, so coercing to null would wrongly deny a valid refreshed session.
 953	      session.authCtx.scopes = freshCtx.scopes;
 954	      // Identity belongs to the MCP session, but worker-originated source
 955	      // conversation is per request. The gateway may reuse the same upstream
 956	      // MCP session across turns for the same user/agent, so keep the mutable
 957	      // auth context current before tools read ToolContext.sourceContext.
 958	      session.authCtx.sourceContext = freshCtx.sourceContext ?? null;
 959	      session.authCtx.adminTools = freshCtx.adminTools ?? null;
