 970	            'Session organization changed. Re-initialize.',
 971	            null,
 972	            400
 973	          );
 974	        }
 975	        // `freshCtx` (scoped) carries a null memberRole — extractAuthContext
 976	        // never looks up membership — so resolve it before it reaches the
 977	        // role-gated tools, mirroring the unscoped branch below.
