    25	
    26	export interface AuthContext {
    27	  organizationId: string | null;
    28	  /**
    29	   * Raw `organization_id` from the OAuth/PAT record itself (null for legacy
    30	   * tokens minted before the binding was required, and always null for
    31	   * session/anonymous). Distinct from `organizationId`, which is the
    32	   * *resolved* org for the request and may come from a URL slug on
    33	   * `/mcp/{slug}` even when the token has no claim of its own.
    34	   */
    35	  tokenOrganizationId: string | null;
    36	  userId: string | null;
    37	  memberRole: string | null;
    38	  agentId: string | null;
    39	  requestedAgentId: string | null;
