    49	  instructions?: string;
    50	  /** `x-lobu-apply-id` when the call belongs to a `lobu apply` run. */
    51	  applyId?: string | null;
    52	  /**
    53	   * Per-turn LIMIT on which tools may execute admin-tier actions. Carried on
    54	   * the builder/system agent's per-run worker token (see
    55	   * WorkerTokenData.adminTools); empty/null for everyone else (no limit —
    56	   * role × scope decide). Non-admin-tier actions are unaffected.
    57	   */
    58	  adminTools?: string[] | null;
    59	}
    60	
    61	/**
    62	 * A resolved TOOL-level failure — the tool could not do its job — which is not
    63	 * thrown, so the MCP boundary must mark it with `isError`. These carry a
    64	 * top-level `error` STRING (query_sql's `{ rows: [], error }`, an action tool's
    65	 * `{ error }`).
    66	 *
    67	 * Deliberately NOT a script failure. `run_sdk` / `query_sdk` execute arbitrary
    68	 * caller code and report the outcome as DATA: `SdkScriptResultSchema` makes
    69	 * `success` a required field and documents `error` as "the thrown error, with
    70	 * script position" (name/message/line/column). When a script throws, the tool
    71	 * itself ran perfectly — it executed the code and returned a faithful report.
    72	 * Marking that `isError` conflates "the sandbox failed to run your code" with
    73	 * "your code ran and threw", which callers must distinguish: `mcpToolsCall`
    74	 * throws on `isError`, so it would stop tests/agents from ever reading the
    75	 * documented `success: false` payload, and `interaction-bridge` would relabel a
    76	 * legitimate script throw as "Tool error:" in agent-visible output.
    77	 */
    78	export function isSoftErrorResult(result: unknown): boolean {
    79	  if (typeof result !== 'object' || result === null) return false;
    80	  const candidate = result as { error?: unknown };
    81	  return typeof candidate.error === 'string' && candidate.error.length > 0;
    82	}
