    84	export function extractAuthContext(c: Context<{ Bindings: Env }>): AuthContext {
    85	  const mcpAuthInfo = c.var.mcpAuthInfo ?? null;
    86	  const tokenType: TokenType =
    87	    mcpAuthInfo?.tokenType === 'pat' ? 'pat'
    88	    : mcpAuthInfo?.tokenType === 'access_token' ? 'oauth'
    89	    : c.var.session?.userId ? 'session'
    90	    : 'anonymous';
    91	  const scopedToOrg = !!c.req.param('orgSlug');
    92	
    93	  return {
    94	    organizationId: c.var.organizationId,
    95	    tokenOrganizationId: mcpAuthInfo?.organizationId ?? null,
    96	    userId: mcpAuthInfo?.userId || c.var.session?.userId || null,
    97	    memberRole: c.var.memberRole,
    98	    agentId: mcpAuthInfo?.agentId ?? null,
    99	    requestedAgentId: mcpAuthInfo?.agentId ?? null,
   100	    sourceContext: mcpAuthInfo?.sourceContext ?? null,
